import{_ as a,o as i,c as o,a2 as r}from"./chunks/framework.B0p3fmqd.js";const f=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"towscenarios/changelog.md","filePath":"towscenarios/changelog.md","lastUpdated":1791039789000}'),t={name:"towscenarios/changelog.md"};function n(l,e,d,s,c,h){return i(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><h2 id="_5-1-0" tabindex="-1">5.1.0 <a class="header-anchor" href="#_5-1-0" aria-label="Permalink to &quot;5.1.0&quot;">​</a></h2><h3 id="new" tabindex="-1">New <a class="header-anchor" href="#new" aria-label="Permalink to &quot;New&quot;">​</a></h3><ul><li>New call-out: a car fire at the roadside. Put it out with a fire extinguisher before it explodes, then recover the wreck.</li><li>New call-outs: a head-on collision and a vehicle rollover, posed and damaged where they were hit.</li><li>Fires can flare back up after being put out, and a burning car explodes, with a warning first, if nobody puts it out. Its payout is reduced when it does.</li><li>The fire bonus is split between everyone who sprayed the fire.</li><li>Pedestrians near a fire scene may flee or stop to film.</li><li>Drivers who arrive late or drive into range find a scene straight away.</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Scene events go to tow drivers and players near the scene instead of every player.</li><li>Default item rewards use standard inventory items.</li><li>Item definitions and icons moved to the documentation.</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>The fire bonus goes to the player who actually sprayed the fire.</li><li>A tow driver can no longer put out fires from across the map.</li><li>Props left behind when the script restarts during an ambulance scene, an ambulance drive, a door being forced or a spares shop purchase.</li></ul><h3 id="config" tabindex="-1">Config <a class="header-anchor" href="#config" aria-label="Permalink to &quot;Config&quot;">​</a></h3><ul><li>Added <code>Config.FireV2</code>, <code>Config.SceneBystanders</code> and <code>Config.AccidentComposer</code>. Every key is optional.</li><li>Added the <code>car_fire</code>, <code>head_on_collision</code> and <code>vehicle_rollover</code> scenarios.</li></ul><h2 id="_5-0-4" tabindex="-1">5.0.4 <a class="header-anchor" href="#_5-0-4" aria-label="Permalink to &quot;5.0.4&quot;">​</a></h2><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Breakdown vehicles and their NPCs failing to spawn, especially at server start or with addon vehicles.</li><li>Failed spawns are cleaned up and the job can be triggered again.</li><li>Script-owned ambulance, chop and repair vehicles left behind after a crash or restart are swept up on start.</li></ul>',13)])])}const g=a(t,[["render",n]]);export{f as __pageData,g as default};
